// How the front side decides what to tell the person today. The structure is the team's: one dated
// message about the body and the psyche, a short explanation, buttons, a choice; critical and not critical,
// light and heavier situations; tell only when something is really wrong. The levels follow NASA's alert
// levels (NASA-STD-3001 Vol 2 Rev F). The working-out of the variants and every threshold below is
// Claude's, at the team's request, and is marked as such on the page: the thresholds are placeholders
// until the team sets them. Code generated by Claude (Anthropic), an AI system.
import { STATUS } from './engine.js';
import { forecast } from './trend.js';

export const LEVEL = { FINE: 0, ATTENTION: 1, ACTION: 2, URGENT: 3 };
export const LEVEL_WORD = ['fine', 'attention', 'needs action', 'urgent'];

// Changes that published flight studies describe as common in flight. A reading outside the Earth norm
// in this direction is still shown, but as "attention", not as a heavier problem.
export const EXPECTED = {
  temp: { side: 'above', text: 'In flight, resting body temperature rises gradually by about 1 °C over two and a half months (Stahn et al., 2017).' },
  sleep: { side: 'below', text: 'On the ISS, astronauts sleep about 6 hours a night on average (Barger et al., 2014).' },
};

// How often a measure is expected, in days; after twice that without a reading the data counts as stale.
export const EXPECTED_EVERY_DAYS = { pulse: 1, bp: 1, temp: 1, sleep: 1, resp: 1, fluid: 1, radiation: 1, co2: 1, cabinTemp: 1, cabinO2: 1, cabinPressure: 1, vo2max: 30 };

// Placeholder thresholds (Claude's), shown on the page as such.
export const RULES = {
  outStreakForAction: 3, // this many readings in a row outside the norm: "needs action"
  psycheDays: 14, // the self-reports of this many last days are looked at
  badDaysForAttention: 3, // bad mood or low energy on this many of those days: "attention"
  badDaysForAction: 6, // ... on this many: "needs action"
  cameraHours: 24, // a camera alarm in this many last hours makes the body "urgent"
};

const DAY = 24 * 60 * 60 * 1000;
const ms = (t) => (t instanceof Date ? t.getTime() : new Date(t).getTime());

function normOf(cell, person) {
  if (cell.normType === 'range') return { min: cell.norm.min, max: cell.norm.max, maxExclusive: Boolean(cell.norm.maxExclusive) };
  if (cell.normType === 'baseline-percent') {
    const base = person && person.baselines ? Number(person.baselines[cell.baselineKey]) : NaN;
    return Number.isFinite(base) ? { min: (base * cell.norm.minPercent) / 100, max: null } : null;
  }
  if (cell.normType === 'below-both') return { min: null, max: cell.norm.sysBelow, maxExclusive: true };
  return null;
}

const valueOf = (cell, v) => (cell.normType === 'below-both' ? Number(v && v.sys) : Number(v));

// One measure of one person: the latest reading, how long it has been outside the norm, the forecast.
export function measureState({ machine, person, cell, mission, now }) {
  const list = machine.history(person.id, cell.indicator);
  const last = list[list.length - 1] || null;
  const norm = normOf(cell, person);
  let streak = 0;
  for (let i = list.length - 1; i >= 0 && list[i].status === STATUS.OUT; i -= 1) streak += 1;
  const side = last && last.status === STATUS.OUT ? (last.side || (cell.normType === 'below-both' ? 'above' : null)) : null;
  const points = list.map((x) => ({ time: x.time, value: valueOf(cell, x.value) }));
  const fc = norm && cell.kind === 'number'
    ? forecast(points, { norm, flatPerDay: 0, now: mission.today, landing: mission.landing, window: { from: mission.launch, to: mission.landing } })
    : null;
  const every = EXPECTED_EVERY_DAYS[cell.indicator];
  const stale = Boolean(every && last && ms(now) - ms(last.time) > 2 * every * DAY);
  return { cell, list, last, norm, streak, side, forecast: fc, stale };
}

// Everything the front side needs for one person today.
export function assess({ machine, person, cells, mission, now }) {
  const body = [];
  const psyche = [];
  const info = [];
  for (const cell of cells) {
    if (cell.section === 'env' || cell.kind !== 'number' || cell.onlyOnEarth) continue;
    const m = measureState({ machine, person, cell, mission, now });
    if (!m.last) continue;
    if (m.stale) info.push({ kind: 'stale', level: LEVEL.FINE, cell, m });
    if (m.last.status === STATUS.OUT) {
      const expected = EXPECTED[cell.indicator] && EXPECTED[cell.indicator].side === m.side ? EXPECTED[cell.indicator] : null;
      const standard = cell.normType === 'baseline-percent' || cell.indicator === 'radiation';
      let level = m.streak >= RULES.outStreakForAction ? LEVEL.ACTION : LEVEL.ATTENTION;
      if (standard) level = LEVEL.ACTION;
      if (expected) level = LEVEL.ATTENTION;
      body.push({ kind: standard ? 'standard' : expected ? 'expected' : 'out', level, cell, m, expected });
    } else if (m.forecast && m.forecast.crossing && !m.forecast.crossing.already) {
      body.push({ kind: 'forecast', level: LEVEL.ATTENTION, cell, m });
    }
  }

  // Camera: an alarm after the question "Are you okay?" makes the body "urgent".
  const cam = machine.history(person.id, 'camera').filter((x) => ms(now) - ms(x.time) <= RULES.cameraHours * 60 * 60 * 1000);
  const alarm = [...cam].reverse().find((x) => x.status === STATUS.OUT);
  if (alarm) body.push({ kind: 'camera', level: LEVEL.URGENT, time: alarm.time, value: alarm.value });

  // Mind: bad mood or low energy on several of the last days (placeholder rule until the team sets one).
  const since = ms(now) - RULES.psycheDays * DAY;
  const badDays = new Set();
  for (const [indicator, low] of [['mood', 'bad'], ['attitude', 'sluggish']]) {
    for (const x of machine.history(person.id, indicator)) {
      if (ms(x.time) >= since && x.value === low) badDays.add(new Date(x.time).toISOString().slice(0, 10));
    }
  }
  if (badDays.size >= RULES.badDaysForAttention) {
    psyche.push({ kind: 'mood', level: badDays.size >= RULES.badDaysForAction ? LEVEL.ACTION : LEVEL.ATTENTION, days: badDays.size });
  }
  const rank = { camera: 0, standard: 1, forecast: 2, out: 3, expected: 4, mood: 5 };
  const order = (a, b) => b.level - a.level || rank[a.kind] - rank[b.kind];
  body.sort(order);
  psyche.sort(order);
  const top = (items) => items.reduce((lv, x) => Math.max(lv, x.level), LEVEL.FINE);
  return { body: { level: top(body), items: body }, psyche: { level: top(psyche), items: psyche }, info };
}

// The ship's own measures (cabin air), the same way, for the status bar.
export function assessShip({ machine, ship, cells, mission, now }) {
  const items = [];
  for (const cell of cells) {
    if (cell.section !== 'env') continue;
    const m = measureState({ machine, person: ship, cell, mission, now });
    if (m.last && m.last.status === STATUS.OUT) items.push({ kind: 'out', level: LEVEL.ATTENTION, cell, m });
  }
  return { level: items.reduce((lv, x) => Math.max(lv, x.level), LEVEL.FINE), items };
}

// The dated message in the team's own words (translated from Russian), for example
// "As of 14 Nov 2026, your physical and mental condition is excellent. Keep it up, well done!"
export function headline(dateText, bodyLevel, psycheLevel) {
  if (bodyLevel === LEVEL.FINE && psycheLevel === LEVEL.FINE) {
    return `As of ${dateText}, your physical and mental condition is excellent. Keep it up, well done!`;
  }
  const word = (lv) => (lv === LEVEL.URGENT ? 'needs help: a doctor has been called'
    : lv === LEVEL.ACTION ? 'needs action'
      : lv === LEVEL.ATTENTION ? 'needs attention' : 'is excellent');
  if (bodyLevel >= psycheLevel) return `As of ${dateText}, your physical condition ${word(bodyLevel)}, your mental condition ${word(psycheLevel)}.`;
  return `As of ${dateText}, your mental condition ${word(psycheLevel)}, your physical condition ${word(bodyLevel)}.`;
}
